void check(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
template<class F> void rejects(F action) {bool caught=false;try {action();}catch(const std::exception&) {caught=true;}check(caught,"Invalid operation accepted");}
std::string read(const std::filesystem::path& file) {std::ifstream input(file,std::ios::binary);return {std::istreambuf_iterator<char>(input),{}};}
void capture(Renderer& renderer,const std::filesystem::path& file) {const auto pixels=renderer.readback();std::ofstream output(file,std::ios::binary);output<<"P6\n"<<renderer.renderWidth()<<" "<<renderer.renderHeight()<<"\n255\n";for(size_t i=0;i<pixels.size();i+=4) output.write(reinterpret_cast<const char*>(pixels.data()+i),3);check(bool(output),"Cannot write UI capture");}
void settingsAndProfiles(const std::filesystem::path& root) {
    const auto installation=root/"fresh-install";check(defaultUserDirectory(installation).is_absolute() && defaultUserDirectory(installation).filename()=="ShardBound","New installation did not use per-user data");check(defaultUserDirectory(installation,true)==installation/"user","Portable data location changed");std::filesystem::create_directories(installation/"user");check(defaultUserDirectory(installation)==installation/"user","Existing portable saves were ignored");
    const auto file=root/"settings.json";GameSettings settings;settings.performance=true;settings.uiScale=.875f;settings.sensitivity=2;settings.musicVolume=.4f;settings.bindings["Jump"]={{Key::R}};settings.save(file);
    auto loaded=GameSettings::load(file);check(loaded.performance && loaded.bindings==settings.bindings && loaded.sensitivity==2 && loaded.uiScale==.875f && loaded.musicVolume==.4f,"Settings did not round-trip");
    const auto before=read(file);loaded.sensitivity=std::numeric_limits<float>::infinity();rejects([&]{loaded.save(file);});check(before==read(file),"Invalid settings replaced valid file");
    auto legacy=nlohmann::json::parse(before);legacy["version"]=1;for(const auto* key:{"sensitivity","ui_scale","performance","effects_volume","music_volume","interface_volume","bindings"}) legacy.erase(key);atomicWrite(file,legacy.dump());
    loaded=GameSettings::load(file);check(!loaded.performance && loaded.sensitivity==1 && loaded.uiScale==1 && loaded.bindings.empty(),"Legacy settings defaults changed");
    auto malformed=nlohmann::json::parse(before);malformed["bindings"]["Jump"][0]["mouse"]=1.5;atomicWrite(file,malformed.dump());rejects([&]{GameSettings::load(file);});
    InputSystem input;input.overrides(settings.bindings);input.bind("Jump",{{Key::Space}});Event event;event.type=EventType::KeyDown;event.key=Key::R;input.process(event);check(input.pressed("Jump"),"Mod binding replaced player override");input.overrides({});check(!input.held("Jump"),"Reset did not restore base binding");
    for(size_t i=0;i<size_t(Key::Count);++i) check(size_t(keyFromName(keyName(Key(i))))==i,"Key names are not stable");
    ModManifest base;base.id="base";base.name="Base";base.version=Version::parse("1.0.0");ModManifest addon;addon.id="addon";addon.name="Addon";addon.version=base.version;addon.dependencies.push_back({"base",">=",base.version,false});
    const auto profilesFile=root/"profiles.json";ModProfiles profiles(profilesFile,{base,addon},{"base","addon"});profiles.toggle("base");check(profiles.enabled().empty(),"Required dependents stayed active");profiles.toggle("addon");check(profiles.enabled().size()==2,"Required dependencies were not enabled");profiles.duplicate();profiles.toggle("addon");profiles.next();check(profiles.enabled().size()==2,"Profiles were not independent");
    profiles.rename("Exploracao");rejects([&]{profiles.rename("   ");});ModProfiles reopened(profilesFile,{base,addon},{"base","addon"});check(reopened.enabled()==profiles.enabled() && reopened.active()==profiles.active(),"Profiles did not persist");
    ModProfiles missing(profilesFile,{base},{"base"});check(!missing.issues().empty(),"Missing profile mod was not diagnosed");missing.toggle("addon");check(missing.issues().empty(),"Missing profile mod could not be removed");
    ModManifest incompatible=addon;incompatible.dependencies[0].version=Version::parse("2.0.0");ModProfiles broken(root/"broken.json",{base,incompatible},{"base","addon"});broken.toggle("addon");rejects([&]{broken.toggle("addon");});check(!broken.enabled().contains("addon"),"Rejected profile change was published");
    FrameProfiler profiler;profiler.sample({10,2});check(profiler.size()==0,"Disabled profiler retained frames");profiler.enabled(true);for(int i=1;i<=700;++i) profiler.sample({double(i),2,i%2?1.:-1.});check(profiler.size()==600,"Frame history is unbounded");
    const auto report=nlohmann::json::parse(encodeData(profiler.report("test-device")));check(report["total_frames"]==700 && report["window_frames"]==600 && report["metrics"]["frame"]["p50"]==400 && report["metrics"]["gpu"]["samples"]==300,"Frame statistics are incorrect");
    profiler.enabled(false);profiler.sample({5,1});check(profiler.size()==600,"Disabled profiler kept recording");profiler.enabled(true);check(profiler.size()==0,"New profiling session retained old samples");rejects([&]{profiler.sample({-1,0});});
    AudioSystem audio(true);audio.setBusVolume(AudioBus::Effects,0);audio.play("assets/core/audio/hit.wav");auto samples=audio.mix(4800);check(std::all_of(samples.begin(),samples.end(),[](float v){return std::abs(v)<.00001f;}),"Muted effects bus remained audible");audio.play("assets/core/audio/hit.wav",false,AudioBus::Music);samples=audio.mix(4800);check(std::any_of(samples.begin(),samples.end(),[](float v){return std::abs(v)>.001f;}),"Effects gain muted music bus");rejects([&]{audio.setBusVolume(AudioBus::Count,1);});
}
void locomotion(float height,bool ceiling) {
    World world;PhysicsSystem physics(world);PlayerController player(world,physics);
    const auto box=[&](Vec3 position,Vec3 half,bool dynamic,Vec3 rotation=Vec3{}) {auto entity=world.create();world.add(entity,TransformComponent{{position}});physics.attachBox(entity,half,dynamic,rotation);return entity;};
    box({0,-.5f,0},{10,.5f,10},false);box({1.5f,height*.5f,0},{.5f,height*.5f,2},false);if(ceiling) box({1.3f,2.8f,0},{1.2f,.2f,2},false);
    const auto actor=box({0,1,0},{.4f,1,.3f},true);player.possess(actor,3);check(player.stepHeight()==0,"Legacy controller gained automatic stepping");player.stepHeight(1.05f);player.movementHeading(0.f);for(int i=0;i<30;++i) physics.step(1.f/60);
    float peak=1;for(int i=0;i<100;++i) {player.move(1,0);physics.step(1.f/60);peak=std::max(peak,world.get<TransformComponent>(actor).local.position.y);}
    const auto p=world.get<TransformComponent>(actor).local.position;
    if(height<1.1f && !ceiling) check(p.x>3 && peak>height+.95f && physics.grounded(actor),"Player did not climb and descend a supported step");
    else check(p.x<.7f && p.y<1.1f,"Step traversal crossed a tall obstacle or low ceiling");
    physics.teleport(actor,{-3,4,0});player.move(1,0);physics.step(1.f/60);check(world.get<TransformComponent>(actor).local.position.y<4 && !physics.grounded(actor),"Ground snapping pulled an airborne player");
}
void slopesAndPassages() {
    {PhysicsWorld rotated;Transform transform;transform.position={0,6,0};transform.rotation={.7f,.8f,.9f};const auto body=rotated.box(transform.position,{2,.2f,1},false,transform.rotation);const auto matrix=transformMatrix(transform);const Vec3 normal{matrix.values[4],matrix.values[5],matrix.values[6]};const auto hit=rotated.raycast({normal.x*2.2f,6+normal.y*2.2f,normal.z*2.2f},{0,6,0});check(hit && hit->body==body && hit->normal.x*normal.x+hit->normal.y*normal.y+hit->normal.z*normal.z>.9999f,"Physics and rendering disagree on combined rotations");}
    World world;PhysicsSystem physics(world);PlayerController player(world,physics);
    auto box=[&](Vec3 position,Vec3 half,bool dynamic,Vec3 rotation=Vec3{}) {auto entity=world.create();world.add(entity,TransformComponent{{position}});physics.attachBox(entity,half,dynamic,rotation);return entity;};
    box({0,-.5f,0},{15,.5f,15},false);box({2,.65f,0},{2,.15f,2},false,{0,0,.35f});const auto actor=box({-.5f,1,0},{.3f,1,.3f},true);player.possess(actor,2);player.stepHeight(1.05f);player.movementHeading(0.f);for(int i=0;i<30;++i) physics.step(1.f/60);
    float peak=1;for(int i=0;i<120;++i) {player.move(1,0);physics.step(1.f/60);peak=std::max(peak,world.get<TransformComponent>(actor).local.position.y);}check(world.get<TransformComponent>(actor).local.position.x>2 && peak>2,"Walkable slope blocked movement");
    box({-.65f,2,7},{.35f,2,1},false);box({.65f,2,7},{.35f,2,1},false);physics.teleport(actor,{0,1,4});physics.attachBox(actor,{.4f,1,.4f},true);for(int i=0;i<90;++i) {player.move(0,1);physics.step(1.f/60);}check(world.get<TransformComponent>(actor).local.position.z<5.7f,"Movement squeezed a collider through a narrow passage");
    box({0,.25f,7},{.3f,.25f,1},false);physics.teleport(actor,{0,1,4});physics.attachBox(actor,{.4f,1,.2f},true,{0,1.5707963f,0});peak=1;for(int i=0;i<180;++i) {player.move(0,1);physics.step(1.f/60);peak=std::max(peak,world.get<TransformComponent>(actor).local.position.y);}check(world.get<TransformComponent>(actor).local.position.z>8.5f && peak>1.45f,"Step sweep ignored the moving collider rotation");
}
void steepSlopeAndContinuousCollision() {
    World world;PhysicsSystem physics(world);PlayerController player(world,physics);
    const auto box=[&](Vec3 position,Vec3 half,bool dynamic,Vec3 rotation=Vec3{}) {auto id=world.create();world.add(id,TransformComponent{{position}});physics.attachBox(id,half,dynamic,rotation);return id;};
    box({0,-.5f,0},{20,.5f,20},false);box({2,1.7f,0},{2,.15f,2},false,{0,0,1.15f});const auto actor=box({0,1,0},{.3f,1,.3f},true);player.possess(actor,2);player.movementHeading(0.f);for(int i=0;i<30;++i) physics.step(1.f/60);
    for(int i=0;i<120;++i) {player.move(1,0);physics.step(1.f/60);}const auto position=world.get<TransformComponent>(actor).local.position;check(position.x<1.8f && position.y<1.5f,"Movement climbed an unwalkable slope");
    check(player.jump(6),"Steep-slope fixture lost floor support");float peak=1;for(int i=0;i<180;++i) {player.move(1,0);physics.step(1.f/60);peak=std::max(peak,world.get<TransformComponent>(actor).local.position.y);}check(peak<3.2f && physics.grounded(actor),"Airborne movement used an unwalkable slope as a climbing motor");
    box({5,4,8},{.06f,4,2},false);physics.teleport(actor,{0,1,8});player.possess(actor,80);for(int i=0;i<60;++i) {player.move(1,0);physics.step(1.f/30);}check(world.get<TransformComponent>(actor).local.position.x<4.75f,"Fast movement crossed a thin wall");
}
