struct ReadinessTestAccess {
    static void run(const std::filesystem::path& root) {
        const auto mods=root/"mods";std::filesystem::copy("content",mods,std::filesystem::copy_options::recursive);std::filesystem::create_directories(mods/"readiness");
        atomicWrite(mods/"readiness/mod.json",R"({"id":"readiness","name":"Profile test","version":"1.0.0","api":"0.1","entry":"main.sl","dependencies":["foundation >= 0.2.0"]})");atomicWrite(mods/"readiness/main.sl","@Entities\nentity Persistent:\n    .label = \"Persistent\"\n@Globals\nactivated = 73\n");
        Application app;app.root_=std::filesystem::current_path();app.modsDirectory_=mods;app.userDirectory_=root/"user";app.explicitMods_=true;app.windowConfig_.hidden=true;app.noVsyncOverride_=true;app.autoWorldName_="Profile A";check(app.initialize(),"Readiness application initialization failed");
        auto& front=*app.frontEnd_;const auto original=*app.currentWorld_;check(app.scripting_->global("readiness","activated").number()==73,"Selected mod did not initialize");
        const auto ramp=app.world_->create("persisted-ramp");app.world_->add(ramp,TransformComponent{{{8,12,8}}});app.physics_->attachBox(ramp,{2,.15f,2},false,{0,0,.35f});app.player_->stepHeight(.75f);
        const auto token=app.world_->create("persistent-token");app.world_->add(token,TransformComponent{{{9,12,9}}});app.world_->add(token,HealthComponent{37,100});auto& identity=app.world_->get<IdentityComponent>(token);identity.owner="readiness";identity.definition="readiness:Persistent";const auto modState=decodeData(R"({"marker":42,"retained":"mod state"})");app.saves_->setState("readiness",modState);app.saveWorld();
        auto invalid=nlohmann::json::parse(read(app.saves_->directory()/"checkpoint.json"));invalid["player"]["step_height"]=-1;atomicWrite(app.saves_->directory()/"invalid-step.json",invalid.dump());const auto entities=app.world_->entityCount();rejects([&]{app.saves_->load("invalid-step");});check(app.world_->entityCount()==entities && app.player_->stepHeight()==.75f,"Invalid movement settings changed the live world");
        front.action(2);app.input_.beginFrame();Event click;click.type=EventType::MouseMove;click.x=300;click.y=500;app.input_.process(click);click.type=EventType::MouseDown;click.mouse=MouseButton::Left;app.input_.process(click);front.update();check(front.settings().performance && app.profiler_.enabled(),"Performance could not be enabled through Settings");
        click.type=EventType::MouseUp;app.input_.process(click);app.input_.beginFrame();front.action(80);const auto ids=actionsForTest(app.input_);const auto where=std::find(ids.begin(),ids.end(),"MoveForward");check(where!=ids.end(),"Movement action missing from controls");front.controlsPage_=size_t(where-ids.begin())/5;front.action(500+int(size_t(where-ids.begin())%5));Event key;key.type=EventType::KeyDown;key.key=Key::R;front.event(key);check(front.settings().bindings.at("MoveForward")[0].key==Key::R,"Controls UI did not save the new key");
        const auto attack=std::find(ids.begin(),ids.end(),"Attack");check(attack!=ids.end(),"Attack binding missing");const auto attackIndex=size_t(attack-ids.begin());front.controlsPage_=attackIndex/5;front.action(500+int(attackIndex%5));app.input_.beginFrame();Event mouse;mouse.type=EventType::MouseMove;mouse.x=200;mouse.y=float(225+int(attackIndex%5)*54);app.input_.process(mouse);mouse.type=EventType::MouseDown;mouse.mouse=MouseButton::Left;app.input_.process(mouse);front.event(mouse);front.update();check(front.rebinding_.empty() && front.settings().bindings.at("Attack")[0].mouse==MouseButton::Left,"Mouse rebinding reactivated its own capture button");mouse.type=EventType::MouseUp;app.input_.process(mouse);app.input_.beginFrame();
        front.draw();app.renderer_->render(Camera{},std::vector<RenderItem>{},front.texture());capture(*app.renderer_,root/"controls.ppm");
        front.action(88);check(app.input_.uiScale()==.75f,"UI scale was not applied to pointer mapping");front.action(83);front.draw();app.renderer_->render(Camera{},std::vector<RenderItem>{},front.texture());capture(*app.renderer_,root/"settings.ppm");front.action(49);check(front.playing(),"Settings did not return to the world");app.config_.maxFrames=80;app.config_.frameLimit=120;app.run();capture(*app.renderer_,root/"performance.ppm");
        auto report=nlohmann::json::parse(encodeData(app.profiler_.report(app.renderer_->deviceName())));check(report["window_frames"].get<size_t>()>50 && !report["metrics"]["gpu"].is_null(),"Real runtime did not collect CPU/GPU timings");check(report["frames"].back()["gameplay"]==true,"Runtime report lost gameplay phase");
        front.action(2);front.action(87);front.action(49);auto& developer=*app.developer_;Event chord;chord.type=EventType::KeyDown;chord.key=Key::PageUp;developer.event(chord);chord.key=Key::PageDown;developer.event(chord);developer.setCamera("free");const auto beforeCamera=developer.camera();Event look;look.type=EventType::MouseDown;look.mouse=MouseButton::Right;developer.event(look);look.type=EventType::MouseMove;look.dx=10;developer.event(look);const auto afterCamera=developer.camera();const float a=std::atan2(beforeCamera.target.x-beforeCamera.eye.x,beforeCamera.target.z-beforeCamera.eye.z),b=std::atan2(afterCamera.target.x-afterCamera.eye.x,afterCamera.target.z-afterCamera.eye.z);check(std::abs(std::remainder(b-a,6.2831853f)-.044f)<.0001f,"Settings sensitivity did not reach camera movement");rejects([&]{developer.sensitivity(std::numeric_limits<float>::quiet_NaN());});
        chord.type=EventType::KeyUp;chord.key=Key::PageUp;developer.event(chord);chord.key=Key::PageDown;developer.event(chord);chord.type=EventType::KeyDown;chord.key=Key::PageUp;developer.event(chord);chord.key=Key::PageDown;developer.event(chord);chord.type=EventType::KeyUp;chord.key=Key::PageUp;developer.event(chord);chord.key=Key::PageDown;developer.event(chord);check(!developer.enabled(),"Sensitivity test retained developer capture");
        app.exportPerformance();check(!std::filesystem::is_empty(app.userDirectory_/"performance"),"Performance export was not written");
        app.scripting_->call("show_ui",{script::Value(std::string("Legacy HUD")),script::Value(false),script::list({}),script::Value(true)});app.ui_->performanceVisible(false);app.ui_->renderWidgets(*app.renderer_);app.renderer_->render(Camera{},std::vector<RenderItem>{},app.ui_->texture());const auto baseline=app.renderer_->readback();app.renderer_->render(Camera{},std::vector<RenderItem>{});const auto blank=app.renderer_->readback();app.ui_->performanceVisible(true);app.ui_->renderWidgets(*app.renderer_);app.renderer_->render(Camera{},std::vector<RenderItem>{},app.ui_->texture(),{},app.ui_->underlay());const auto composite=app.renderer_->readback();const size_t pixel=(size_t(300)*1280+100)*4;check(!std::equal(baseline.begin()+pixel,baseline.begin()+pixel+3,blank.begin()+pixel),"HUD fixture did not paint the sampled pixel");check(std::equal(baseline.begin()+pixel,baseline.begin()+pixel+3,composite.begin()+pixel),"Performance overlay erased a legacy HUD");
        front.action(32);front.action(4);front.draw();app.renderer_->setCanvasOverlay(true);app.renderer_->render(Camera{},std::vector<RenderItem>{},front.texture());capture(*app.renderer_,root/"mods.ppm");front.action(11);front.profiles_->toggle("readiness");front.refreshProfile();const auto second=front.createRecord("Profile B","profile-b");check(!second.mods.contains("readiness"),"New world ignored the selected profile");front.open(second,false);rejects([&]{app.scripting_->global("readiness","activated");});front.action(32);
        front.open(original,true);check(app.player_->stepHeight()==.75f && app.physics_->description(app.world_->find("persisted-ramp")).rotation.z==.35f,"Movement or rotated collision did not survive save/load");check(app.scripting_->global("readiness","activated").number()==73,"Existing world used the active profile instead of its saved mod set");front.action(32);
        const auto generation=front.storage().read(original.id).definition.json();front.profileWorld_=original.id;front.action(94);front.maintenance_.wait();front.update();const auto changed=front.storage().read(original.id);check(!changed.mods.contains("readiness") && changed.definition.json()==generation && !front.storage().backups(original.id).empty(),"Applying a world profile changed generation or omitted its backup");front.open(changed,true);rejects([&]{app.scripting_->global("readiness","activated");});check(!app.world_->find("persistent-token") && app.saves_->state("readiness")==modState,"Disabled mod data became live or was discarded");app.saveWorld();front.action(32);
        front.profiles_->toggle("readiness");front.refreshProfile();front.profileWorld_=original.id;front.action(94);front.maintenance_.wait();front.update();front.open(front.storage().read(original.id),true);check(app.world_->get<HealthComponent>(app.world_->find("persistent-token")).current==37 && app.saves_->state("readiness")==modState,"Re-enabling a mod did not restore its saved entity and state");
        front.action(2);front.action(77);check(!app.profiler_.enabled(),"Settings did not disable performance collection");const auto count=app.profiler_.size();front.action(49);app.config_.maxFrames=3;app.run();check(app.profiler_.size()==count && app.renderer_->stats().gpuMilliseconds<0,"Disabled profiler still submitted or retained new timings");app.shutdown();
    }
    static std::vector<std::string> actionsForTest(const InputSystem& input) {std::vector<std::string> result;for(const auto& [id,b]:input.bindings()) {(void)b;if(id!="Quit") result.push_back(id);}return result;}
};
