int main() {try {const auto root=std::filesystem::current_path()/"user"/("readiness-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(root);game::settingsAndProfiles(root);for(const float h:{.25f,.5f,1.f,2.f}) game::locomotion(h,false);game::locomotion(1,true);game::slopesAndPassages();game::steepSlopeAndContinuousCollision();game::ReadinessTestAccess::run(root);std::cout<<"PASS readiness: locomotion, profiles, Settings, controls, audio and actual GPU profiling\n";return 0;}catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}}
